#!/bin/sh
# usage: results.sh <operation uuid>
Q=/Users/ryanducharme/.claude/jira-watch/state/results/OR-2949/scratch/q.sh
echo "fired:"; $Q "select f.rule_identifier, f.trigger, f.details::text from \"demo-demo\".rule_fired_results f join \"demo-demo\".rule_execution_contexts x on x.id=f.rule_execution_context_id where x.operation_id='$1' order by f.created_date"
echo "not-fired (antibiotic):"; $Q "select n.rule_identifier, n.explanation from \"demo-demo\".rule_not_fired_results n join \"demo-demo\".rule_execution_contexts x on x.id=n.rule_execution_context_id where x.operation_id='$1' and n.rule_identifier ilike '%antibiotic%' order by n.created_date"
echo "any row for retired rule:"; $Q "select count(*) from \"demo-demo\".rule_not_fired_results n join \"demo-demo\".rule_execution_contexts x on x.id=n.rule_execution_context_id where x.operation_id='$1' and n.rule_identifier='a-known-procedure-missing-antibiotic'"; $Q "select count(*) from \"demo-demo\".rule_fired_results f join \"demo-demo\".rule_execution_contexts x on x.id=f.rule_execution_context_id where x.operation_id='$1' and f.rule_identifier='a-known-procedure-missing-antibiotic'"; $Q "select count(*) from \"demo-demo\".rule_failure_results f join \"demo-demo\".rule_execution_contexts x on x.id=f.rule_execution_context_id where x.operation_id='$1' and f.rule_identifier='a-known-procedure-missing-antibiotic'" 2>&1
